(1, 40, 'Priyanshu Garg', 'Development Task', 'Development', 'Task Assignment', 'gf', 'Pending', '2025-09-29', '2025-09-29 14:14:25', '2025-09-29 14:14:25'),
(2, 40, 'Priyanshu Garg', 'Development Task', 'Development', 'Task Assignment', 'WhatsApp Bulk SMS and Template seteup', 'Pending', '2025-09-30', '2025-09-30 17:33:07', '2025-09-30 17:33:07'),
(3, 40, 'Priyanshu Garg', 'Development Task', 'Development', 'Task Assignment', 'AI Doctor Application', 'Pending', '2026-01-24', '2026-01-21 10:34:09', '2026-01-21 10:34:09'),
(4, 85, 'Priti Bandewar', 'Development Task', 'Development', 'Task Assignment', 'Dentalguru Pro Bug Fixing', 'Pending', '2026-01-21', '2026-01-21 10:34:36', '2026-01-21 10:34:36'),
(5, 40, 'Priyanshu Garg', 'Development Task', 'Development', 'Task Assignment', 'AI Doctor Application Receptionist Module', 'Pending', '2026-01-22', '2026-01-21 10:35:45', '2026-01-21 10:35:45'),
(6, 40, 'Priyanshu Garg', 'Development Task', 'Development', 'Task Assignment', 'AI Doctor Application Doctor Module', 'Pending', '2026-01-23', '2026-01-21 10:36:05', '2026-01-21 10:36:05'),
(7, 120, 'Mohd Qaisar Moin', 'Development Task', 'Development', 'Task Assignment', 'For the Bloom Herb project, the website needs to be developed in React. Currently, the client-side website is fully built in HTML.\n\nThe backend admin panel has already been developed separately in React, and the client-side HTML website also exists as a separate codebase.\n\nYour task will be to merge both into a single unified React application. The existing HTML website must be converted into React and integrated properly so that the entire system runs as one complete React-based application.\n\nYou can pull the latest code from Git and proceed accordingly.', 'Pending', '2026-03-03', '2026-03-01 09:18:18', '2026-03-01 09:18:18'),
(8, 119, 'Ashish Dubey ', 'Development Task', 'Development', 'Task Assignment', 'Ashish, you have two days to complete the Natura project.\n\nAfter that, please update us on what tasks are still pending so they can be addressed after the client meeting.\n\nYou will then be required to move on and join the second project accordingly.', 'Pending', '2026-03-01', '2026-03-01 09:19:47', '2026-03-01 09:19:47'),
(9, 85, 'Priti Bandewar', 'Development Task', 'Development', 'Task Assignment', 'Complete Chandrayu \nCheck all baner images and product images. catalog \ncontent \nwhatsapp icon call icon \nchatbot \nall app\'s are free used \n\nmulti product option \n\nMeeting MOM \n', 'Pending', '2026-03-01', '2026-03-01 09:22:41', '2026-03-01 09:22:41'),
(10, 39, 'Dev Ansh Dubey ', 'Development Task', 'Development', 'Task Assignment', 'Complete Dentalguru Doctor Module \nWith PDF Part ', 'Pending', '2026-03-01', '2026-03-01 09:23:15', '2026-03-01 09:23:15'),
(11, 40, 'Priyanshu Garg', 'Development Task', 'Development', 'Task Assignment', 'ASAP Compelte DOON School \nlandig Page \nAnd Upload in New server \nCreate backend \nDynamic Blog \nImages \nCreate New Section for Acedamic Activity ', 'Pending', '2026-03-01', '2026-03-01 09:24:25', '2026-03-01 09:24:25'),
(12, 40, 'Priyanshu Garg', 'Development Task', 'Development', 'Task Assignment', 'SF Update Oauth login setup', 'Pending', '2026-03-10', '2026-03-10 12:14:20', '2026-03-10 12:14:20'),
(13, 120, 'Mohd Qaisar Moin', 'Development Task', 'Development', 'Task Assignment', 'Complete today\'s WhatsApp and Mail Reminders and messages ', 'Pending', '2026-04-04', '2026-04-04 05:17:55', '2026-04-04 05:17:55');
